--
-- Table structure for table `mitra`
--

CREATE TABLE `mitra` (
  `mitra_id` int(10) UNSIGNED NOT NULL,
  `user_id` int(10) UNSIGNED NOT NULL,
  `nama_lengkap` varchar(100) NOT NULL,
  `no_hp` varchar(20) NOT NULL,
  `nama_brand` varchar(100) DEFAULT NULL,
  `jenis_usaha` varchar(100) DEFAULT NULL,
  `kepemilikan_usaha` varchar(100) DEFAULT NULL,
  `kebutuhan_per_order_kg` int(11) DEFAULT NULL,
  `frekuensi_beli_per_bulan` int(11) DEFAULT NULL,
  `status_verifikasi` enum('pending','diterima','ditolak') DEFAULT 'pending',
  `catatan_verifikasi` text DEFAULT NULL,
  `dokumen_ktp` varchar(255) DEFAULT NULL,
  `dokumen_npwp` varchar(255) DEFAULT NULL,
  `tanggal_daftar` date DEFAULT NULL,
  `provinsi_id` int(10) UNSIGNED DEFAULT NULL,
  `kota_id` int(10) UNSIGNED DEFAULT NULL,
  `kecamatan_id` int(10) UNSIGNED DEFAULT NULL,
  `kelurahan_id` varchar(13) DEFAULT NULL,
  `kode_pos` varchar(10) DEFAULT NULL,
  `alamat_jalan` text DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

