(1, 'PRD0001', 2, 'ATPS Potong 6', 'Produk ATPS (Ayam Tanpa Paha dan Sayap) berasal dari karkas yang paha bawah dan sayapnya dipotong/diambil untuk penggantian bagian tersebut yang kategori memar, patah atau salah potong\r\n\r\nKlasifikasi Potongan\r\nPotong 6\r\n\r\nSpesifikasi\r\n\r\nProduk ATPS tidak memar dada, paha atas, dan punggung\r\nTidak ada bulu dan kulit ari\r\nBayah dan lemak abdomen masih ada/menempel', 'kg', 27000.00, '1752490291_109987b3f8436b297744.png', '2025-07-14 17:51:31', '2025-08-01 14:27:48', 551.00, 'aktif'),
(2, 'PRD0002', 1, 'Karkas', 'Karkas merupakan daging ayam utuh yg telah disembelih dan dibersihkan bulu, organ dalam, kaki & kepalanya', 'kg', 30000.00, '1752490574_a71c6a38c227475e72a2.png', '2025-07-14 17:56:14', '2025-08-05 10:59:54', 224.00, 'aktif'),
(3, 'PRD0003', 3, 'Boneless Paha Ayam', 'Boneless paha ayam, kadang disebut juga fillet paha, merupakan produk paha ayam yang sudah dipisahkan antara daging dan tulangnya', 'kg', 25000.00, '1752490786_c6677dbaee394bdb6493.png', '2025-07-14 17:59:46', '2025-07-18 06:19:27', 700.00, 'aktif'),
(4, 'PRD0004', 4, 'Kerongkong', 'Kerongkong ayam atau tulang punggung ayam merupakan produk sampingan dari boneless.\r\n\r\nSpesifikasi \r\n\r\nProduk segar, tidak berbau, tidak berlendir, dan tidak berubah warna\r\nWarna produk merah segar, tidak pucat', 'kg', 17000.00, '1752491005_a5b3acffd8ac096616a7.png', '2025-07-14 18:03:25', '2025-07-18 02:22:18', 0.00, 'aktif'),
(5, 'KPD1752777385', 2, 'ATPS Potong 5', 'Produk ATPS (Ayam Tanpa Paha dan Sayap) berasal dari karkas yang paha bawah dan sayapnya dipotong/diambil untuk penggantian bagian tersebut yang kategori memar, patah atau salah potong\r\n\r\nKlasifikasi Potongan\r\nPotong 5\r\n\r\nSpesifikasi\r\n\r\nProduk ATPS tidak memar dada, paha atas, dan punggung\r\nTidak ada bulu dan kulit ari\r\nBayah dan lemak abdomen masih ada/menempel\r\n ', 'kg', 27000.00, '1752777385_4304fe5f47bfb9462a6e.png', '2025-07-18 01:36:25', '2025-07-18 01:36:25', 0.00, 'aktif'),
(6, 'KPD1752777518', 2, 'Ayam Potong 12 / Ayam Parting 12', 'Produk ayam yang dipotong sesuai kebutuhan, Tanpa ekor, tidak ada bulu, tidak ada kulit ari, tanpa lemak, usus pendek dan darah.\r\n\r\nKlasifikasi Potongan\r\nPotongan 12 (Paha atas bawah, dada tulang dan dada mentok)\r\n\r\nSpesifikasi\r\n\r\nTidak memar bagian dada, paha, sayap\r\nTidak patah paha dan sayap\r\nTidak ada bulu halus atau kasar\r\nTidak ada kulit dari bayah/maras\r\nTidak ada lemak berlebih dan ekor di potong', 'kg', 30000.00, '1752777518_acb00e7edeab8f973b21.png', '2025-07-18 01:38:38', '2025-07-19 12:35:07', 287.00, 'aktif'),
(7, 'KPD1752777566', 2, 'Ayam Potong 14 / Ayam Parting 14', 'Produk ayam yang dipotong sesuai kebutuhan, Tanpa ekor, tidak ada bulu, tidak ada kulit ari, tanpa lemak, usus pendek dan darah.\r\n\r\nKlasifikasi Potongan\r\nPotongan 14 (Paha atas bawah, dada tulang dan dada mentok)\r\n\r\nSpesifikasi\r\n\r\nTidak memar bagian dada, paha, sayap\r\nTidak patah paha dan sayap\r\nTidak ada bulu halus atau kasar\r\nTidak ada kulit dari bayah/maras\r\nTidak ada lemak berlebih dan ekor di potong', 'kg', 30000.00, '1752777566_bb330f5b7e66d687de47.png', '2025-07-18 01:39:26', '2025-07-18 01:39:26', 0.00, 'aktif'),
(8, 'KPD1752777614', 2, 'Ayam Parting 10 / Ayam Potong 10', 'Produk ayam yang dipotong sesuai kebutuhan, Tanpa ekor, tidak ada bulu, tidak ada kulit ari, tanpa lemak, usus pendek dan darah.\r\n\r\nKlasifikasi Potongan\r\nPotongan 10 (Paha atas bawah, dada tulang dan dada mentok)\r\n\r\nSpesifikasi\r\n\r\nTidak memar bagian dada, paha, sayap\r\nTidak patah paha dan sayap\r\nTidak ada bulu halus atau kasar\r\nTidak ada kulit dari bayah/maras\r\nTidak ada lemak berlebih dan ekor di potong', 'kg', 30000.00, '1752777614_5c43c684213913e24139.png', '2025-07-18 01:40:14', '2025-07-18 01:40:14', 0.00, 'aktif'),
(9, 'KPD1752777674', 2, 'Ayam Potong 9 / Ayam Parting 9', 'Produk ayam yang dipotong sesuai kebutuhan, Tanpa ekor, tidak ada bulu, tidak ada kulit ari, tanpa lemak, usus pendek dan darah.\r\n\r\nKlasifikasi Potongan\r\nPotongan 9 (Paha atas bawah, dada tulang dan dada mentok)\r\n\r\nSpesifikasi\r\n\r\nTidak memar bagian dada, paha, sayap\r\nTidak patah paha dan sayap\r\nTidak ada bulu halus atau kasar\r\nTidak ada kulit dari bayah/maras\r\nTidak ada lemak berlebih dan ekor di potong', 'kg', 27000.00, '1752777674_3bc2b53c60e254c2b54b.png', '2025-07-18 01:41:14', '2025-07-18 01:41:14', 0.00, 'aktif'),
(10, 'KPD1752777722', 2, 'Ayam Potong 8 / Ayam Parting 8', 'Produk ayam yang dipotong sesuai kebutuhan, Tanpa ekor, tidak ada bulu, tidak ada kulit ari, tanpa lemak, usus pendek dan darah\r\n\r\nKlasifikasi Potongan\r\nPotongan 8 (Paha atas bawah, dada tulang dan dada mentok)\r\n\r\nSpesifikasi\r\n\r\nTidak memar bagian dada, paha, sayap\r\nTidak patah paha dan sayap\r\nTidak ada bulu halus atau kasar\r\nTidak ada kulit dari bayah/maras\r\nTidak ada lemak berlebih dan ekor di potong', 'kg', 27000.00, '1752777722_3095d3867530908e11b3.png', '2025-07-18 01:42:02', '2025-07-18 01:42:02', 0.00, 'aktif'),
(11, 'KPD1752777778', 2, 'Ayam Potong 6 / Ayam Parting 6', 'Produk ayam yang dipotong sesuai kebutuhan, Tanpa ekor, tidak ada bulu, tidak ada kulit ari, tanpa lemak, usus pendek dan darah.\r\n\r\nKlasifikasi Potongan\r\nPotongan 6 (Dada sayap, paha bawah dan paha atas atau dada, sayap dan paha utuh)\r\n\r\nSpesifikasi\r\n\r\nTidak memar bagian dada, paha, sayap\r\nTidak patah paha dan sayap\r\nTidak ada bulu halus atau kasar\r\nTidak ada kulit dari bayah/maras\r\nTidak ada lemak berlebih dan ekor di potong', 'kg', 27000.00, '1752777778_4c147efacfd412ea5235.png', '2025-07-18 01:42:58', '2025-07-18 01:42:58', 0.00, 'aktif'),
(12, 'KPD1752777846', 3, 'Boneless Paha Kulit Ayam', 'Boneless paha kulit ayam merupakan boneless paha ayam yang kulitnya masih menempel, terdapat 2 grade untuk produk boneless paha kulit ayam, yaitu Boneless Paha Kulit Ayam Spesial dan Boneless Paha Kulit Ayam Grade B\r\n\r\nBoneless Paha Kulit Ayam Spesial\r\n\r\nTidak memar di bagian daging lebih dari 1cm\r\nProduk fresh, tidak pucat\r\nTidak kehijauan\r\nAroma khas daging tidak bau\r\nKulit tidak ada bulu dan kulit ari\r\n \r\n\r\nBoneless Paha Kulit Ayam Grade B\r\n\r\nProduk ada memar di bagian daging 1cm s/d 3cm\r\nAda sedikit kehijauan\r\nAroma daging kurang sedap, dan berlendir\r\nKulit pucat dan berubah warna', 'kg', 25000.00, '1752777846_ef6a5c4806f2cea7da94.png', '2025-07-18 01:44:06', '2025-07-18 01:44:06', 0.00, 'aktif'),
(13, 'KPD1752777935', 3, 'Boneless Dada Kulit Ayam', 'Boneless dada kulit ayam, merupakan daging ayam tanpa tulang yang dibuat dengan cara memisahkan tulang dengan daging pada bagian dada, tanpa melepas kulit ayam.\r\n\r\nKlasifikasi ukuran\r\n\r\n200-250 gram\r\n250-400 gram\r\nGrade \r\n\r\nGrade A love\r\nGrade A Non Love\r\nGrade C / Reject\r\nKlasifikasi Potongan\r\n\r\nLove\r\nNon Love\r\n \r\n\r\nBoneless Dada Kulit Ayam Grade A Love\r\n\r\nProduk berbentuk love dan masih ada kulit\r\nProduk fresh tidak berbau, tidak berlendir, dan tidab berubah warna\r\nTidak ada memar di bagian daging\r\nAdanya lemak tergantung permintaan customer\r\nWarna produk merah segar, tidak pucat\r\nBoneless Dada Kulit Ayam Grade A non-love\r\n\r\nProduk tidak berbentuk love namu kulit masih ada\r\nProduk fresh tidak bau, tidak berlendir dan tidak berubah warna\r\ntidak ada memar di bagian daging\r\nWarna produk merah segar, tidak pucat', 'kg', 25000.00, '1752777935_95d4b74e97a061d83b77.png', '2025-07-18 01:45:35', '2025-07-18 01:45:35', 0.00, 'aktif'),
(14, 'KPD1754024126', 5, 'Tulang Rawan Ayam', 'Tulang rawan ayam merupakan bagian tulang ayam yang strukturnya lebih lentur.', 'kg', 12000.00, '1754024126_f9e6e49cc17f06df654a.png', '2025-08-01 11:55:26', '2025-08-01 11:55:26', 0.00, 'aktif');

